/**
 * Python string helpers.
 *
 * Only what the CLI needs: `repr()` of a str, which shows up verbatim inside
 * argparse's "invalid float value: 'abc'" diagnostics and inside the
 * `KeyError: 'XYZ'` line of an unhandled-exception traceback.
 */

const SIMPLE_ESCAPES = new Map([
  ['\\', '\\\\'],
  ['\n', '\\n'],
  ['\r', '\\r'],
  ['\t', '\\t'],
]);

/**
 * True for code points CPython's `unicode_repr` considers printable, i.e.
 * everything except the Cc/Cf/Cs/Co/Cn/Zl/Zp/Zs categories (space itself is
 * kept printable). Anything else is escaped as \xNN / \uNNNN / \UNNNNNNNN.
 */
function isPrintable(ch) {
  if (ch === ' ') return true;
  return !/[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]/u.test(ch);
}

function escapeUnprintable(ch) {
  const cp = ch.codePointAt(0);
  if (cp <= 0xff) return '\\x' + cp.toString(16).padStart(2, '0');
  if (cp <= 0xffff) return '\\u' + cp.toString(16).padStart(4, '0');
  return '\\U' + cp.toString(16).padStart(8, '0');
}

/**
 * `repr(s)` for a Python str: single quotes by default, double quotes when the
 * value contains a single quote but no double quote.
 */
export function pyRepr(s) {
  const quote = s.includes("'") && !s.includes('"') ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    if (ch === quote) out += '\\' + ch;
    else if (SIMPLE_ESCAPES.has(ch)) out += SIMPLE_ESCAPES.get(ch);
    else if (isPrintable(ch)) out += ch;
    else out += escapeUnprintable(ch);
  }
  return out + quote;
}

/**
 * `str.upper()`. Python uppercases per the Unicode simple/full uppercase
 * mapping, which is what JS `toUpperCase()` implements as well; the one thing
 * to avoid is locale-sensitive casing (Turkish dotless i, etc.).
 */
export function pyUpper(s) {
  return s.toUpperCase();
}

