/**
 * Python `float` semantics: parsing a str into a double the way `float(s)`
 * does, and rendering a double back the way `repr()`/`str()` does.
 *
 * Both directions matter here. Parsing decides which strings argparse accepts
 * for `type=float`; rendering decides the exact digit string that `Money`
 * hands to `Decimal`, and therefore the exponent of the result.
 */

/** Characters Python's `Py_UNICODE_ISSPACE` treats as whitespace. */
const PY_SPACE = /[\t\n\v\f\r \x1c-\x1f\x85\p{Zs}\p{Zl}\p{Zp}]/u;
const UNICODE_DIGIT = /\p{Nd}/u;

function isDecimalDigitChar(ch) {
  return ch !== undefined && UNICODE_DIGIT.test(ch);
}

/**
 * Decimal value of a Unicode Nd code point. Every Nd run is a block of ten
 * consecutive code points ordered 0..9, so walking back to the start of the
 * contiguous run and taking the offset modulo ten yields the digit value even
 * when two blocks happen to abut.
 */
function decimalDigitValue(cp) {
  let start = cp;
  while (isDecimalDigitChar(String.fromCodePoint(start - 1))) start -= 1;
  return (cp - start) % 10;
}

/**
 * CPython's `_PyUnicode_TransformDecimalAndSpaceToASCII`: any Unicode decimal
 * digit becomes its ASCII counterpart and any Unicode space becomes ' ', so
 * `float('٥.٥')` and `float(' 5')` behave like their ASCII spellings.
 */
export function transformDecimalAndSpaceToAscii(s) {
  let out = '';
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (cp < 0x80) out += ch;
    else if (PY_SPACE.test(ch)) out += ' ';
    else if (UNICODE_DIGIT.test(ch)) out += String(decimalDigitValue(cp));
    else out += ch;
  }
  return out;
}

const INF_NAN_RE = /^[+-]?(?:inf(?:inity)?|nan)$/i;
const NUMBER_RE = /^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$/;

/**
 * PEP 515: an underscore is only legal directly between two digits, which
 * accepts '1_0.5', '1.0_5' and '1e1_0' while rejecting '_1', '1_', '1__0',
 * '1_.5' and '1e_1'.
 */
function stripUnderscores(s) {
  const chars = [...s];
  for (let i = 0; i < chars.length; i += 1) {
    if (chars[i] !== '_') continue;
    const prev = chars[i - 1];
    const next = chars[i + 1];
    const isDigit = (c) => c !== undefined && c >= '0' && c <= '9';
    if (!isDigit(prev) || !isDigit(next)) return null;
  }
  return chars.filter((c) => c !== '_').join('');
}

/**
 * `float(s)`. Returns the double, or `null` when Python would raise
 * ValueError (which argparse turns into "invalid float value: ...").
 */
export function pyFloat(s) {
  const text = transformDecimalAndSpaceToAscii(s).trim();
  if (INF_NAN_RE.test(text)) {
    if (/nan$/i.test(text)) return NaN;
    return text.startsWith('-') ? -Infinity : Infinity;
  }
  const bare = stripUnderscores(text);
  if (bare === null || !NUMBER_RE.test(bare)) return null;
  // Number() and CPython's strtod are both correctly rounded, and both fold
  // out-of-range exponents to +/-Infinity or a signed zero.
  return Number(bare);
}

/**
 * Shortest round-tripping digits of a finite, non-zero, positive double,
 * normalised so that the value is `0.<digits> * 10**decpt`.
 *
 * `String(v)` already yields the shortest round-tripping digit string, so only
 * its placement of the decimal point has to be renormalised.
 */
function shortestDigits(v) {
  const m = /^(\d+)(?:\.(\d+))?(?:e([+-]\d+))?$/.exec(String(v));
  const intPart = m[1];
  const fracPart = m[2] ?? '';
  const exp = m[3] ? Number(m[3]) : 0;

  let digits = intPart + fracPart;
  let decpt = intPart.length + exp;
  const firstSignificant = digits.search(/[1-9]/);
  digits = digits.slice(firstSignificant);
  decpt -= firstSignificant;
  digits = digits.replace(/0+$/, '');
  return { digits, decpt };
}

/**
 * `repr(x)` / `str(x)` of a Python float: shortest round-tripping digits, a
 * mandatory '.0' on integral values, and a switch to exponential notation
 * exactly when `decpt <= -4 or decpt > 16` (CPython's 'r' format code).
 */
export function pyFloatRepr(x) {
  if (Number.isNaN(x)) return 'nan';
  if (x === Infinity) return 'inf';
  if (x === -Infinity) return '-inf';

  const sign = x < 0 || Object.is(x, -0) ? '-' : '';
  if (x === 0) return sign + '0.0';

  const { digits, decpt } = shortestDigits(Math.abs(x));
  if (decpt <= -4 || decpt > 16) {
    const mantissa = digits.length > 1 ? `${digits[0]}.${digits.slice(1)}` : digits;
    const e = decpt - 1;
    const eSign = e < 0 ? '-' : '+';
    return `${sign}${mantissa}e${eSign}${String(Math.abs(e)).padStart(2, '0')}`;
  }
  if (decpt <= 0) return `${sign}0.${'0'.repeat(-decpt)}${digits}`;
  if (decpt >= digits.length) return `${sign}${digits}${'0'.repeat(decpt - digits.length)}.0`;
  return `${sign}${digits.slice(0, decpt)}.${digits.slice(decpt)}`;
}

