/**
 * Unsigned arbitrary-precision integers held as plain decimal digit strings.
 *
 * The decimal engine needs exact integer arithmetic on coefficients that can
 * exceed the 2**53 range, and it needs it in base 10 so that scaling by powers
 * of ten stays exact. These helpers keep values normalised: no leading zeros,
 * and zero is always the single digit "0".
 */

/** Drops leading zeros, collapsing an all-zero string to "0". */
export function normalize(a) {
  const trimmed = a.replace(/^0+(?=\d)/, '');
  return trimmed === '' ? '0' : trimmed;
}

export function isZero(a) {
  return a === '0';
}

/** -1, 0 or 1 for a < b, a == b, a > b. */
export function compare(a, b) {
  if (a.length !== b.length) return a.length < b.length ? -1 : 1;
  if (a === b) return 0;
  return a < b ? -1 : 1;
}

/** a - b, requiring a >= b. */
export function subtract(a, b) {
  const out = [];
  let borrow = 0;
  for (let i = 0; i < a.length; i += 1) {
    const ai = a.charCodeAt(a.length - 1 - i) - 48;
    const bi = i < b.length ? b.charCodeAt(b.length - 1 - i) - 48 : 0;
    let d = ai - bi - borrow;
    if (d < 0) {
      d += 10;
      borrow = 1;
    } else {
      borrow = 0;
    }
    out.push(d);
  }
  return normalize(out.reverse().join(''));
}

/** a * 10**n. */
export function shiftLeft(a, n = 1) {
  return isZero(a) ? '0' : a + '0'.repeat(n);
}

/** Number of significant digits; zero counts as one digit, as in the spec. */
export function digitCount(a) {
  return a.length;
}

