/**
 * A focused implementation of the General Decimal Arithmetic specification —
 * the same standard CPython's `decimal` module implements.
 *
 * Scope is deliberately narrow: construction from a numeric string, true
 * division under a precision-28 / ROUND_HALF_EVEN context, and the
 * to-scientific-string conversion used by `str(Decimal)`. That is exactly the
 * surface `Money(amount, currency) / 2` touches.
 *
 * Values are stored sign-and-magnitude as an unsigned coefficient (a decimal
 * digit string) and an integer exponent, so `coefficient * 10**exponent` is
 * the exact value and trailing zeros are significant.
 */

import { compare, isZero, normalize, shiftLeft, subtract } from './bigdigits.mjs';

export const ROUND_HALF_EVEN = 'ROUND_HALF_EVEN';

/** CPython's default decimal context. */
export const DefaultContext = { precision: 28, rounding: ROUND_HALF_EVEN };

const NAN = 'NaN';
const INFINITY = 'Infinity';

const PARSE_RE =
  /^(?<sign>[-+])?(?:(?<inf>inf(?:inity)?)|(?<nan>s?nan)(?<diag>\d*)|(?:(?<int>\d*)(?:\.(?<frac>\d*))?)(?:[eE](?<exp>[-+]?\d+))?)$/i;

export class Decimal {
  /**
   * @param {number} sign 0 for positive, 1 for negative
   * @param {string} coefficient unsigned decimal digits
   * @param {number|string} exponent integer exponent, or 'n'/'N'/'F' for NaN/sNaN/Infinity
   */
  constructor(sign, coefficient, exponent) {
    this.sign = sign;
    this.coefficient = coefficient;
    this.exponent = exponent;
    Object.freeze(this);
  }

  static fromString(value) {
    const m = PARSE_RE.exec(String(value).trim());
    if (m === null) throw new Error(`invalid literal for Decimal: ${value}`);
    const { sign, inf, nan, diag, int: intPart, frac, exp } = m.groups;
    const negative = sign === '-' ? 1 : 0;
    if (inf !== undefined) return new Decimal(negative, '0', 'F');
    if (nan !== undefined) {
      return new Decimal(negative, diag === '' ? '0' : normalize(diag), nan.length === 3 ? 'n' : 'N');
    }
    const digits = (intPart ?? '') + (frac ?? '');
    if (digits === '') throw new Error(`invalid literal for Decimal: ${value}`);
    const exponent = (exp ? Number(exp) : 0) - (frac ?? '').length;
    return new Decimal(negative, normalize(digits), exponent);
  }

  static fromInt(value) {
    const negative = value < 0 ? 1 : 0;
    return new Decimal(negative, String(Math.abs(value)), 0);
  }

  get isSpecial() {
    return typeof this.exponent === 'string';
  }

  get isNaN() {
    return this.exponent === 'n' || this.exponent === 'N';
  }

  get isInfinite() {
    return this.exponent === 'F';
  }

  get isZero() {
    return !this.isSpecial && isZero(this.coefficient);
  }

  /** True division, `self / other`. */
  divide(other, context = DefaultContext) {
    return divide(this, other, context);
  }

  /** `str(Decimal)`: the specification's to-scientific-string conversion. */
  toString() {
    const sign = this.sign ? '-' : '';
    if (this.isInfinite) return sign + INFINITY;
    if (this.isNaN) {
      const prefix = this.exponent === 'N' ? 's' : '';
      const diagnostic = isZero(this.coefficient) ? '' : this.coefficient;
      return sign + prefix + NAN + diagnostic;
    }

    const digits = this.coefficient;
    const adjusted = this.exponent + digits.length - 1;
    if (this.exponent <= 0 && adjusted >= -6) {
      if (this.exponent === 0) return sign + digits;
      if (digits.length > -this.exponent) {
        const point = digits.length + this.exponent;
        return `${sign}${digits.slice(0, point)}.${digits.slice(point)}`;
      }
      return `${sign}0.${'0'.repeat(-this.exponent - digits.length)}${digits}`;
    }

    const mantissa = digits.length > 1 ? `${digits[0]}.${digits.slice(1)}` : digits;
    const eSign = adjusted < 0 ? '-' : '+';
    return `${sign}${mantissa}E${eSign}${Math.abs(adjusted)}`;
  }
}

/** Adds one to an unsigned digit string. */
function increment(digits) {
  const out = digits.split('');
  let i = out.length - 1;
  for (; i >= 0; i -= 1) {
    if (out[i] === '9') {
      out[i] = '0';
    } else {
      out[i] = String(Number(out[i]) + 1);
      return out.join('');
    }
  }
  return '1' + out.join('');
}

/**
 * `divide` from the specification.
 *
 * The quotient is generated one digit at a time by repeated subtraction. The
 * loop stops as soon as the remainder is exhausted *and* the running exponent
 * has reached the "ideal exponent" (exponent of the dividend minus that of the
 * divisor) — which is what makes `Decimal('4.0') / 2` keep its trailing zero
 * and print "2.0", while `Decimal('1E+16') / 2` prints "5E+15".
 */
function divide(a, b, context) {
  const sign = a.sign ^ b.sign;

  if (a.isNaN) return new Decimal(a.sign, a.coefficient, 'n');
  if (b.isNaN) return new Decimal(b.sign, b.coefficient, 'n');
  if (a.isInfinite && b.isInfinite) return new Decimal(0, '0', 'n'); // InvalidOperation
  if (a.isInfinite) return new Decimal(sign, '0', 'F');
  if (b.isInfinite) return new Decimal(sign, '0', 0);
  if (b.isZero) {
    if (a.isZero) return new Decimal(0, '0', 'n'); // InvalidOperation
    return new Decimal(sign, '0', 'F'); // DivisionByZero
  }

  const idealExponent = a.exponent - b.exponent;
  if (a.isZero) return new Decimal(sign, '0', idealExponent);

  let remainder = a.coefficient;
  let divisor = b.coefficient;
  let adjust = 0;
  while (compare(remainder, divisor) < 0) {
    remainder = shiftLeft(remainder);
    adjust += 1;
  }
  while (compare(remainder, shiftLeft(divisor)) >= 0) {
    divisor = shiftLeft(divisor);
    adjust -= 1;
  }

  let digits = '';
  for (;;) {
    let digit = 0;
    while (compare(remainder, divisor) >= 0) {
      remainder = subtract(remainder, divisor);
      digit += 1;
    }
    digits += String(digit);
    if ((isZero(remainder) && adjust >= 0) || digits.length === context.precision) break;
    remainder = shiftLeft(remainder);
    adjust += 1;
  }

  let exponent = idealExponent - adjust;
  if (!isZero(remainder)) {
    // Inexact: the discarded tail is `remainder / divisor`. Round half even by
    // comparing twice the remainder against the divisor.
    const doubled = shiftLeft(remainder, 1);
    const tail = compare(doubled, shiftLeft(divisor, 1).slice(0, -1) + '0');
    const cmp = tail !== 0 ? compare(doubled, divisor) * 0 + compare(doubled, divisor) : 0;
    const lastDigit = digits.charCodeAt(digits.length - 1) - 48;
    if (cmp > 0 || (cmp === 0 && lastDigit % 2 === 1)) {
      digits = increment(digits);
      if (digits.length > context.precision) {
        digits = digits.slice(0, context.precision);
        exponent += 1;
      }
    }
  }

  return new Decimal(sign, normalize(digits), exponent);
}

