header = '''/**
 * The currency registry backing `moneyed`.
 *
 * The upstream package ships a table of ISO 4217 codes plus a long tail of
 * historical and fund codes (BYR, DEM, XAU, XTS, ...). Only the set of codes
 * it accepts is observable from the outside, so that is what is reproduced
 * here: %d codes, recovered by probing the reference build across the whole
 * three-letter space and confirmed exhaustive (every other code raises
 * CurrencyDoesNotExist).
 */

/** Whitespace-separated so the table stays readable and diffable. */
const CURRENCY_CODES = `
%s
`;

/** A currency, keyed by its (upper-case) code. */
export class Currency {
  constructor(code) {
    this.code = code;
    Object.freeze(this);
  }

  toString() {
    return this.code;
  }
}

/** code -> Currency, mirroring `moneyed.CURRENCIES`. */
export const CURRENCIES = new Map(
  CURRENCY_CODES.trim()
    .split(/\\s+/)
    .map((code) => [code, new Currency(code)]),
);
''' % (len(codes), block)
open('/output/lib/currencies.mjs', 'w').write(header)
print(open('/output/lib/currencies.mjs').read()[:600])
PY

node -e "
