/**
 * The slice of `moneyed` this CLI exercises: `Money`, currency lookup, and the
 * exceptions they raise.
 *
 * The behavioural details that matter downstream, all confirmed against the
 * reference build:
 *   - a float amount is converted with `Decimal(str(amount))`, not
 *     `Decimal(amount)`, so `Money(0.1, 'USD') / 2` is exactly 0.05;
 *   - the currency code is upper-cased before lookup ('usd' resolves, ' USD'
 *     does not, because no stripping happens);
 *   - `money / number` divides the amount and keeps the currency.
 */

import { CURRENCIES } from './currencies.mjs';
import { Decimal } from './decimal.mjs';
import { pyFloatRepr } from './pyfloat.mjs';
import { pyRepr, pyUpper } from './pystr.mjs';

/** `moneyed.classes.CurrencyDoesNotExist`. */
export class CurrencyDoesNotExist extends Error {
  constructor(code) {
    super(`No currency with code ${code} is defined.`);
    this.name = 'moneyed.classes.CurrencyDoesNotExist';
    this.code = code;
    // The underlying dict lookup surfaces in the traceback as a chained
    // KeyError, so keep the key that failed alongside the message.
    this.cause = { name: 'KeyError', message: pyRepr(code) };
  }
}

/** `moneyed.get_currency`. */
export function getCurrency(code) {
  const key = pyUpper(String(code));
  const currency = CURRENCIES.get(key);
  if (currency === undefined) throw new CurrencyDoesNotExist(key);
  return currency;
}

/** Coerces an amount to `Decimal` the way `Money.__init__` does. */
function toDecimal(amount) {
  if (amount instanceof Decimal) return amount;
  if (typeof amount === 'number') return Decimal.fromString(pyFloatRepr(amount));
  return Decimal.fromString(String(amount));
}

/** `moneyed.Money`. */
export class Money {
  constructor(amount = Decimal.fromString('0.0'), currency = 'XYZ') {
    this.amount = toDecimal(amount);
    this.currency = currency instanceof Object && 'code' in currency ? currency : getCurrency(currency);
  }

  /** `self / other` for a numeric divisor: scales the amount, keeps the currency. */
  divide(other) {
    const divisor = other instanceof Decimal ? other : Decimal.fromInt(other);
    return new Money(this.amount.divide(divisor), this.currency);
  }

  toString() {
    return `${this.amount.toString()} ${this.currency.code}`;
  }
}

