/**
 * `linecache.getline` for traceback rendering.
 *
 * A frozen build records the script's filename as a relative path ('test6.py')
 * and does not bundle the source, so Python resolves it against the current
 * working directory at failure time: the traceback shows the offending source
 * line when a `test6.py` happens to sit in the cwd, and omits it otherwise.
 */

import { readFileSync } from 'node:fs';

const cache = new Map();

/** Splits like Python's `readlines()`: line terminators are kept. */
function readLines(filename) {
  const text = readFileSync(filename, 'utf8').replace(/\r\n?/g, '\n');
  const lines = text.split('\n').map((line, i, all) => (i === all.length - 1 ? line : `${line}\n`));
  if (lines[lines.length - 1] === '') lines.pop();
  return lines;
}

/**
 * The raw 1-based line (terminator included) or '' when the file or line is
 * unavailable — exactly `linecache.getline`'s contract.
 */
export function getline(filename, lineno) {
  if (!cache.has(filename)) {
    try {
      cache.set(filename, readLines(filename));
    } catch {
      cache.set(filename, null);
    }
  }
  const lines = cache.get(filename);
  if (lines === null) return '';
  return lines[lineno - 1] ?? '';
}

