/**
 * Rendering of the CPython traceback that a PyInstaller-frozen script prints
 * when an exception escapes `__main__`.
 *
 * Two details of the frozen build are reproduced here:
 *   - library frames show no source line, because the packaged sources are not
 *     on disk, while the script's own frame shows one whenever a file of that
 *     name is resolvable from the cwd (see ./pylinecache.mjs);
 *   - the run ends with PyInstaller's own "[PYI-<pid>:ERROR]" banner.
 *
 * Column anchors (the `^^^^` line, Python 3.11+) are compile-time constants of
 * the original source, so they are supplied by the caller and only clipped
 * against the line that was actually read.
 */

import { getline } from './pylinecache.mjs';

/**
 * @typedef {{colno: number, endColno: number}} Anchors
 * @typedef {{file: string, line: number, name: string, anchors?: Anchors}} Frame
 * @typedef {{frames: Frame[], type: string, message: string}} PyException
 */

const HEADER = 'Traceback (most recent call last):';
const CHAIN = '\nDuring handling of the above exception, another exception occurred:\n\n';
const INDENT = '    ';

/**
 * The `^^^^` line for a frame, or '' when Python would omit it: no anchors, an
 * empty source line, or an anchor range covering the whole displayed line.
 *
 * Offsets are byte offsets into the raw line (terminator included) and are
 * clipped to it, then rebased onto the stripped line that gets displayed. The
 * geometry is exact for the recorded source; a source line that has drifted
 * from the compiled one can only be approximated, since Python mixes
 * compile-time columns with run-time text.
 */
function formatAnchors(rawLine, anchors) {
  const stripped = rawLine.trim();
  if (stripped === '') return '';
  const leading = rawLine.length - rawLine.trimStart().length;
  const start = Math.min(anchors.colno, rawLine.length) - leading;
  const end = Math.min(anchors.endColno, rawLine.length) - leading;
  if (end <= start) return '';
  if (start === 0 && end === stripped.length) return '';
  return `${INDENT}${' '.repeat(Math.max(start, 0))}${'^'.repeat(end - start)}\n`;
}

function formatFrame(frame) {
  let out = `  File "${frame.file}", line ${frame.line}, in ${frame.name}\n`;
  const rawLine = getline(frame.file, frame.line);
  const stripped = rawLine.trim();
  if (rawLine === '') return out;
  out += `${INDENT}${stripped}\n`;
  if (frame.anchors) out += formatAnchors(rawLine, frame.anchors);
  return out;
}

function formatException(exception) {
  let out = `${HEADER}\n`;
  for (const frame of exception.frames) out += formatFrame(frame);
  return `${out}${exception.type}: ${exception.message}\n`;
}

/**
 * Formats a chain of exceptions (oldest first, as Python prints them) followed
 * by the PyInstaller banner.
 *
 * @param {PyException[]} chain
 * @param {string} scriptName name shown in the banner, e.g. 'test6'
 * @param {number} pid
 */
export function formatUnhandledException(chain, scriptName, pid) {
  const body = chain.map(formatException).join(CHAIN);
  return `${body}[PYI-${pid}:ERROR] Failed to execute script '${scriptName}' due to unhandled exception!\n`;
}

