/**
 * Rendering of the CPython traceback that a PyInstaller-frozen script prints
 * when an exception escapes `__main__`.
 *
 * The frozen build reports library frames without source lines (the sources
 * are not bundled) but keeps the source line and caret markers for frames of
 * the script itself, and finishes with PyInstaller's own "[PYI-<pid>:ERROR]"
 * line. Both are reproduced so the failure output lines up with the reference.
 */

/**
 * @typedef {{file: string, line: number, name: string, source?: string, caret?: string}} Frame
 * @typedef {{frames: Frame[], type: string, message: string}} PyException
 */

const HEADER = 'Traceback (most recent call last):';
const CHAIN =
  '\nDuring handling of the above exception, another exception occurred:\n\n';

function formatException(exception) {
  let out = `${HEADER}\n`;
  for (const frame of exception.frames) {
    out += `  File "${frame.file}", line ${frame.line}, in ${frame.name}\n`;
    if (frame.source !== undefined) {
      out += `    ${frame.source}\n`;
      if (frame.caret !== undefined) out += `        ${frame.caret}\n`;
    }
  }
  return `${out}${exception.type}: ${exception.message}\n`;
}

