 * @param {number} pid
 */
export function formatUnhandledException(chain, scriptName, pid) {
  const body = chain.map(formatException).join(CHAIN);
  return `${body}[PYI-${pid}:ERROR] Failed to execute script '${scriptName}' due to unhandled exception!\n`;
}

