/**
 * A port of the argparse behaviour this CLI depends on.
 *
 * Only optional (dash-prefixed) arguments with `nargs=None` are supported,
 * which is all `test6.py` declares, but within that scope the semantics follow
 * CPython closely: unique-prefix abbreviation, `--opt=value`, the
 * negative-number heuristic that lets `-5.5` through but not `-5e3`, `--` as
 * an end-of-options marker that an optional may *not* consume as a value,
 * required-argument checking ahead of unrecognised-argument reporting, and the
 * exact wording and exit codes of the diagnostics.
 */

import { pyRepr } from './pystr.mjs';

/** Thrown for `parser.error()`; carries argparse's exit status of 2. */
export class ArgumentParserExit extends Error {
  constructor(status, message = '') {
    super(message);
    this.status = status;
    this.printMessage = message;
  }
}

/** argparse's `_negative_number_matcher`. */
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

class Action {
  constructor({ optionStrings, dest, type, required = false, help, action = 'store', metavar }) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.type = type;
    this.required = required;
    this.help = help;
    this.action = action;
    this.metavar = metavar ?? dest.toUpperCase();
  }

  /** `_get_action_name`: what diagnostics call this argument. */
  get name() {
    return this.optionStrings.join('/');
  }

  /** `_format_action_invocation`: "-h, --help" or "--amount AMOUNT". */
  formatInvocation() {
    if (this.action === 'help') return this.optionStrings.join(', ');
    return this.optionStrings.map((s) => `${s} ${this.metavar}`).join(', ');
  }

  formatUsage() {
    if (this.action === 'help') return `[${this.optionStrings[0]}]`;
    const body = `${this.optionStrings[0]} ${this.metavar}`;
    return this.required ? body : `[${body}]`;
  }
}

export class ArgumentParser {
  constructor({ prog, addHelp = true } = {}) {
    this.prog = prog;
    this.actions = [];
    this.optionStringActions = new Map();
    if (addHelp) {
      this.addArgument(['-h', '--help'], { action: 'help', help: 'show this help message and exit' });
    }
  }

  addArgument(optionStrings, { type, required = false, help, action = 'store', dest, metavar } = {}) {
    const names = Array.isArray(optionStrings) ? optionStrings : [optionStrings];
    const longest = names.find((n) => n.startsWith('--')) ?? names[0];
    const resolvedDest = dest ?? longest.replace(/^-+/, '').replace(/-/g, '_');
    const argument = new Action({
      optionStrings: names,
      dest: resolvedDest,
      type,
      required,
      help,
      action,
      metavar,
    });
    this.actions.push(argument);
    for (const name of names) this.optionStringActions.set(name, argument);
    return argument;
  }

  formatUsage() {
    return `usage: ${this.prog} ${this.actions.map((a) => a.formatUsage()).join(' ')}\n`;
  }

  /**
   * `HelpFormatter.format_help`. The help column is placed exactly where
   * argparse puts it: two spaces past the longest invocation, capped at 24.
   */
  formatHelp() {
    const indent = 2;
    const invocations = this.actions.map((a) => a.formatInvocation());
    const actionMaxLength = Math.max(...invocations.map((s) => s.length)) + indent;
    const helpPosition = Math.min(actionMaxLength + 2, 24);

    let out = `${this.formatUsage()}\noptions:\n`;
    for (const [i, action] of this.actions.entries()) {
      const invocation = invocations[i];
      if (!action.help) {
        out += `${' '.repeat(indent)}${invocation}\n`;
        continue;
      }
      if (invocation.length + indent <= helpPosition - 2) {
        out += `${' '.repeat(indent)}${invocation.padEnd(helpPosition - indent)}${action.help}\n`;
      } else {
        out += `${' '.repeat(indent)}${invocation}\n${' '.repeat(helpPosition)}${action.help}\n`;
      }
    }
    return out;
  }

  /** `parser.error()`: usage plus one line on stderr, then exit status 2. */
  error(message) {
    throw new ArgumentParserExit(2, `${this.formatUsage()}${this.prog}: error: ${message}\n`);
  }

  /** `_parse_optional`: classify one token. */
  #parseOptional(argString) {
    if (argString === '') return null;
    if (!argString.startsWith('-')) return null;
    if (this.optionStringActions.has(argString)) {
      return { action: this.optionStringActions.get(argString), optionString: argString, explicitArg: null };
    }
    if (argString.length === 1) return null; // a lone '-' is not an option
    if (argString.includes('=')) {
      const index = argString.indexOf('=');
      const optionString = argString.slice(0, index);
      if (this.optionStringActions.has(optionString)) {
        return {
          action: this.optionStringActions.get(optionString),
          optionString,
          explicitArg: argString.slice(index + 1),
        };
      }
    }
    const matches = this.#getOptionTuples(argString);
    if (matches.length > 1) {
      const options = matches.map((m) => m.optionString).join(', ');
      this.error(`ambiguous option: ${argString} could match ${options}`);
    }
    if (matches.length === 1) return matches[0];
    if (NEGATIVE_NUMBER.test(argString)) return null; // no option looks like a number
    if (argString.includes(' ')) return null;
    return { action: null, optionString: argString, explicitArg: null }; // unknown option
  }

  /** `_get_option_tuples`: unique-prefix abbreviation for '--' options. */
  #getOptionTuples(argString) {
    const result = [];
    if (!argString.startsWith('--')) return result;
    let prefix = argString;
    let explicitArg = null;
    if (argString.includes('=')) {
      const index = argString.indexOf('=');
      prefix = argString.slice(0, index);
      explicitArg = argString.slice(index + 1);
    }
    for (const [optionString, action] of this.optionStringActions) {
      if (optionString.startsWith(prefix)) result.push({ action, optionString, explicitArg });
    }
    return result;
  }

  parseArgs(args) {
    const [namespace, extras] = this.parseKnownArgs(args);
    if (extras.length > 0) this.error(`unrecognized arguments: ${extras.join(' ')}`);
    return namespace;
  }

  parseKnownArgs(args) {
    const namespace = Object.create(null);
    for (const action of this.actions) {
      if (action.action === 'store') namespace[action.dest] = null;
    }

    // Classify every token up front: 'O' optional, 'A' plain argument,
    // '-' the end-of-options marker. Everything after '--' is forced to 'A'.
    const pattern = [];
    const optionTuples = new Map();
    let afterDoubleDash = false;
    for (const [i, argString] of args.entries()) {
      if (afterDoubleDash) {
        pattern.push('A');
        continue;
      }
      if (argString === '--') {
        afterDoubleDash = true;
        pattern.push('-');
        continue;
      }
      const optionTuple = this.#parseOptional(argString);
      if (optionTuple === null) {
        pattern.push('A');
      } else {
        optionTuples.set(i, optionTuple);
        pattern.push('O');
      }
    }

    const extras = [];
    const seenActions = new Set();
    let index = 0;
    while (index < args.length) {
      if (pattern[index] !== 'O') {
        // No positional actions are declared, so anything that is not an
        // option (including '--' itself) is left over.
        extras.push(args[index]);
        index += 1;
        continue;
      }

      const { action, optionString, explicitArg } = optionTuples.get(index);
      if (action === null) {
        extras.push(args[index]);
        index += 1;
        continue;
      }

      let value;
      if (explicitArg !== null) {
        value = explicitArg;
        index += 1;
      } else {
        // `_get_nargs_pattern` strips '-' from an optional's pattern, so an
        // optional can never swallow '--' as its value.
        if (pattern[index + 1] !== 'A') {
          this.error(`argument ${action.name}: expected one argument`);
        }
        value = args[index + 1];
        index += 2;
      }

      seenActions.add(action);
      this.#takeAction(action, value, namespace);
    }

    const missing = this.actions.filter((a) => a.required && !seenActions.has(a));
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.map((a) => a.name).join(', ')}`);
    }
    return [namespace, extras];
  }

  #takeAction(action, value, namespace) {
    if (action.action === 'help') {
      throw new ArgumentParserExit(0, this.formatHelp());
    }
    namespace[action.dest] = this.#getValue(action, value);
  }

  /**
   * `_get_value`: run the `type` callable and report failures argparse-style.
   * A type is `{ name, convert }` where `convert` returns `{ ok, value }`, so a
   * successful conversion to NaN stays distinguishable from a ValueError.
   */
  #getValue(action, argString) {
    if (!action.type) return argString;
    const converted = action.type.convert(argString);
    if (!converted.ok) {
      this.error(`argument ${action.name}: invalid ${action.type.name} value: ${pyRepr(argString)}`);
    }
    return converted.value;
  }
}

