        // option (including '--' itself) is left over.
        extras.push(args[index]);
        index += 1;
        continue;
      }

      const { action, optionString, explicitArg } = optionTuples.get(index);
      if (action === null) {
        extras.push(args[index]);
        index += 1;
        continue;
      }

      let value;
      if (explicitArg !== null) {
        value = explicitArg;
        index += 1;
      } else {
        // `_get_nargs_pattern` strips '-' from an optional's pattern, so an
        // optional can never swallow '--' as its value.
        if (pattern[index + 1] !== 'A') {
          this.error(`argument ${action.name}: expected one argument`);
        }
        value = args[index + 1];
        index += 2;
      }

      seenActions.add(action);
      this.#takeAction(action, value, namespace);
    }

    const missing = this.actions.filter((a) => a.required && !seenActions.has(a));
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.map((a) => a.name).join(', ')}`);
    }
    return [namespace, extras];
  }

  #takeAction(action, value, namespace) {
    if (action.action === 'help') {
      throw new ArgumentParserExit(0, this.formatHelp());
    }
    namespace[action.dest] = this.#getValue(action, value);
  }

  /**
   * `_get_value`: run the `type` callable and report failures argparse-style.
   * A type is `{ name, convert }` where `convert` returns `{ ok, value }`, so a
   * successful conversion to NaN stays distinguishable from a ValueError.
   */
  #getValue(action, argString) {
    if (!action.type) return argString;
    const converted = action.type.convert(argString);
    if (!converted.ok) {
      this.error(`argument ${action.name}: invalid ${action.type.name} value: ${pyRepr(argString)}`);
    }
