toolUseResult.originalFile:
/**
 * Node port of `test6.py`:
 *
 *     parser.add_argument('--amount', type=float, required=True)
 *     parser.add_argument('--currency', type=str, required=True)
 *     m = Money(args.amount, args.currency)
 *     halved = m / 2
 *     print(halved.amount)
 *
 * Run it exactly like the reference build:
 *     node test6.mjs --amount 133.13 --currency GBP   ->  66.565
 */

import { ArgumentParser, ArgumentParserExit } from './lib/argparse.mjs';
import { CurrencyDoesNotExist, Money } from './lib/moneyed.mjs';
import { pyFloat } from './lib/pyfloat.mjs';
import { formatUnhandledException } from './lib/pytraceback.mjs';

/**
 * argparse takes `prog` from `os.path.basename(sys.argv[0])`. It is pinned to
 * the reference program's name so usage, help and error text match it
 * byte-for-byte rather than reading 'test6.mjs'.
 */
const PROG = 'test6_executable';
const SCRIPT = 'test6';

/** `type=float`. */
const FLOAT = {
  name: 'float',
  convert(argString) {
    const value = pyFloat(argString);
    return value === null ? { ok: false } : { ok: true, value };
  },
};

/** `type=str`: never fails, but keeps the declaration faithful. */
const STR = {
  name: 'str',
  convert(argString) {
    return { ok: true, value: argString };
  },
};

function buildParser() {
  const parser = new ArgumentParser({ prog: PROG });
  parser.addArgument(['--amount'], { type: FLOAT, required: true });
  parser.addArgument(['--currency'], { type: STR, required: true });
  return parser;
}

/** The traceback Python produces when `get_currency` misses. */
function currencyTraceback(error) {
  return formatUnhandledException(
    [
      {
        frames: [{ file: 'moneyed/classes.py', line: 400, name: 'get_currency' }],
        type: error.cause.name,
        message: error.cause.message,
      },
      {
        frames: [
          {
            file: 'test6.py',
            line: 10,
            name: '<module>',
            source: 'm = Money(args.amount, args.currency)',
            caret: '^'.repeat('Money(args.amount, args.currency)'.length),
          },
          { file: 'moneyed/classes.py', line: 196, name: '__init__' },
          { file: 'moneyed/classes.py', line: 402, name: 'get_currency' },
        ],
        type: error.name,
        message: error.message,
      },
    ],
    SCRIPT,
    process.pid,
  );
}

function main(argv) {
  const parser = buildParser();

  let args;
  try {
    args = parser.parseArgs(argv);
  } catch (error) {
    if (!(error instanceof ArgumentParserExit)) throw error;
    // Help goes to stdout and exits 0; usage errors go to stderr and exit 2.
    const stream = error.status === 0 ? process.stdout : process.stderr;
    stream.write(error.printMessage);
    return error.status;
  }

  try {
    const m = new Money(args.amount, args.currency);
    const halved = m.divide(2);
    process.stdout.write(`${halved.amount.toString()}\n`);
  } catch (error) {
    if (!(error instanceof CurrencyDoesNotExist)) throw error;
    process.stderr.write(currencyTraceback(error));
    return 1;
  }
  return 0;
}

process.exitCode = main(process.argv.slice(2));
